(2, 'Coastal Seafood', 'coastal-seafood', 'Premium dried and fresh seafood including prawns, bombil, mackerel, and traditional Konkan fish', '/images/categories/seafood.jpg', NULL, 1, 2, 'Authentic Konkan Coastal Seafood Online | Konkan Bazaar', 'Premium dried fish, prawns, bombil, and fresh coastal seafood from the Konkan coast'),
(3, 'Coconut Products', 'coconut-products', 'Pure coconut oil, dried coconut, coconut milk, and traditional coconut-based products', '/images/categories/coconut.jpg', NULL, 1, 3, 'Pure Coconut Products Online | Konkan Bazaar', 'Cold-pressed coconut oil, dried coconut, and traditional coconut products from Konkan'),
(4, 'Konkan Rice Varieties', 'konkan-rice-varieties', 'Premium Indrayani, Ambemohar, Red Rice, and traditional Konkan rice varieties', '/images/categories/rice.jpg', NULL, 1, 4, 'Buy Authentic Konkan Rice Online | Konkan Bazaar', 'Premium Indrayani, Ambemohar, Red Rice, and traditional rice varieties from Konkan region'),
(5, 'Kokum & Beverages', 'kokum-beverages', 'Kokum juice, Sol Kadhi, and traditional Konkan cooling beverages', '/images/categories/kokum.jpg', NULL, 1, 5, 'Buy Kokum & Konkan Beverages Online | Konkan Bazaar', 'Refreshing Kokum juice, Sol Kadhi, and traditional Konkan beverages'),
(6, 'Pickles & Chutneys', 'pickles-chutneys', 'Traditional Konkan pickles, chutneys, and condiments made with authentic recipes', '/images/categories/pickles.jpg', NULL, 1, 6, 'Traditional Konkan Pickles & Chutneys Online | Konkan Bazaar', 'Authentic Konkan style pickles, chutneys, and traditional condiments'),
(7, 'Cashew & Dry Fruits', 'cashew-dry-fruits', 'Premium Konkan cashews, raw, roasted, spiced, and cashew Feni', '/images/categories/cashew.jpg', NULL, 1, 7, 'Premium Konkan Cashews Online | Konkan Bazaar', 'Premium cashew nuts from Goa and Konkan region - raw, roasted, and spiced varieties'),
(8, 'Natural Spices', 'natural-spices', 'Pure, organic spices from the Konkan region including black pepper, cardamom, cloves', '/images/categories/spices.jpg', NULL, 1, 8, 'Organic Konkan Spices Online | Konkan Bazaar', 'Pure organic spices from the Konkan region - pepper, cardamom, cloves, and more'),
(9, 'Organic Jaggery & Sweeteners', 'organic-jaggery-sweeteners', 'Pure organic jaggery, palm jaggery, honey, and natural sweeteners from Konkan', '/images/categories/jaggery.jpg', NULL, 1, 9, 'Organic Jaggery & Natural Sweeteners Online | Konkan Bazaar', 'Pure organic jaggery, palm jaggery, and natural sweeteners from Konkan farms'),
(10, 'Traditional Snacks', 'traditional-snacks', 'Traditional Konkan snacks including chakli, murukku, poha, and festive treats', '/images/categories/snacks.jpg', NULL, 1, 10, 'Traditional Konkan Snacks Online | Konkan Bazaar', 'Authentic Konkan snacks and traditional festive treats made with traditional recipes'),
(11, 'Handmade Crafts', 'handmade-crafts', 'Handcrafted Konkan souvenirs, decor, and traditional items', '/images/categories/crafts.jpg', NULL, 1, 11, 'Handmade Konkan Crafts Online | Konkan Bazaar', 'Authentic handcrafted Konkan souvenirs, home decor, and traditional items'),
(12, 'Monsoon Specials', 'monsoon-specials', 'Special Konkan monsoon products including dried fish, bhajji mixes, and seasonal treats', '/images/categories/monsoon.jpg', NULL, 1, 12, 'Konkan Monsoon Specials Online | Konkan Bazaar', 'Special monsoon products from Konkan - traditional snacks, dried fish, and seasonal treats');
