INSERT INTO products (id, name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
(1, 'Devgad Alphonso Mango - Premium Box (12 pcs)', 'devgad-alphonso-mango-premium-box-12-pcs', 'Handpicked Devgad Alphonso mangoes from the famous Devgad region of Sindhudurg district. These golden-yellow mangoes are known for their unparalleled sweetness, rich aroma, and buttery texture. Each mango is carefully selected at the perfect ripeness and packed in a traditional mango box for gifting.', 'Premium Devgad Alphonso mangoes - 12 handpicked pieces in gift box', 1899.00, 2499.00, 200, 'MAN-ALP-001', 1, 'Konkan Bazaar Select', 3000, 'box', 1, 1, 1, 1, 'Devgad, Sindhudurg', 7, 'Fresh Alphonso Mangoes', '{"calories": 150, "serving_size": "100g", "vitamin_c": "37mg", "vitamin_a": "54mcg", "fiber": "1.6g", "sugar": "14.8g"}', 'Store at room temperature. Once ripe, refrigerate and consume within 2-3 days.', 4.80, 128, 1500, 25000),
(2, 'Ratnagiri Alphonso Mango - Family Pack (6 pcs)', 'ratnagiri-alphonso-mango-family-pack-6-pcs', 'Premium Ratnagiri Alphonso mangoes sourced directly from the orchards of Ratnagiri district. Known as the King of Mangoes, these have a distinct sweet taste with hints of saffron and honey. Perfect for desserts, smoothies, or eating fresh.', 'Premium Ratnagiri Alphonso mangoes - 6 large pieces', 999.00, 1299.00, 300, 'MAN-ALP-002', 1, 'Konkan Bazaar Select', 1800, 'pack', 1, 1, 1, 1, 'Ratnagiri', 7, 'Fresh Alphonso Mangoes', '{"calories": 150, "serving_size": "100g", "vitamin_c": "37mg", "vitamin_a": "54mcg", "fiber": "1.6g", "sugar": "14.8g"}', 'Store at room temperature. Refrigerate after ripening.', 4.70, 95, 1200, 18000),
(3, 'Devgad Hapus Mango Pulp (1kg)', 'devgad-hapus-mango-pulp-1kg', 'Pure Devgad Hapus mango pulp made from handpicked, fully ripened Alphonso mangoes. No added sugar, no preservatives, no artificial colors. The rich golden pulp captures the authentic taste of Konkan mangoes, perfect for making mango shakes, desserts, and smoothies all year round.', 'Pure Devgad Alphonso mango pulp - No preservatives, No added sugar', 599.00, 799.00, 500, 'MAN-PLP-001', 1, 'Konkan Delight', 1000, 'jar', 1, 1, 1, 1, 'Devgad, Sindhudurg', 365, 'Pure Alphonso Mango Pulp', '{"calories": 120, "serving_size": "100g", "sugar": "28g", "fiber": "0.5g", "vitamin_c": "25mg"}', 'Store in cool dry place. Refrigerate after opening and consume within 7 days.', 4.60, 200, 3000, 35000),
(4, 'Alphonso Mango Gift Hamper (Premium)', 'alphonso-mango-gift-hamper-premium', 'Luxury gift hamper containing 12 premium Devgad Alphonso mangoes, 250g premium cashews, 200g mango pulp, and a traditional Konban handwoven basket. Perfect Diwali or festival gifting.', 'Luxury mango gift hamper with cashews, pulp, and handwoven basket', 2999.00, 3999.00, 100, 'MAN-GFT-001', 1, 'Konkan Bazaar Select', 5000, 'hamper', 0, 1, 1, 0, 'Devgad & Ratnagiri', 10, 'Alphonso Mangoes, Cashews, Mango Pulp', '{"calories": 200, "serving_size": "250g", "includes": "12 mangoes, 250g cashews, 200g pulp"}', 'Gift box - handle with care. Mangoes at room temperature.', 4.90, 45, 350, 8000),
(5, 'Payri Mango (1 Dozen)', 'payri-mango-1-dozen', 'Traditional Payri mangoes from the farms of Sindhudurg. These small to medium-sized mangoes have a unique sweet-tangy flavor profile that mango connoisseurs love. The skin is greenish-yellow with a distinct red blush. Known for their fibrous texture and intense mango aroma.', 'Traditional Payri mangoes - 12 pieces with unique sweet-tangy flavor', 699.00, 899.00, 250, 'MAN-PAY-001', 1, 'Konkan Heritage', 2400, 'dozen', 0, 0, 1, 1, 'Sindhudurg', 5, 'Fresh Payri Mangoes', '{"calories": 140, "serving_size": "100g", "vitamin_c": "30mg", "fiber": "2.0g", "sugar": "13g"}', 'Store at room temperature. Use within 3-5 days of ripening.', 4.30, 65, 800, 12000),
(6, 'Mankurad Mango (1 Dozen)', 'mankurad-mango-1-dozen', 'Premium Mankurad mangoes from Goa, known for their distinct sweet taste with a hint of spice. These medium-sized mangoes have smooth, yellow skin and deep orange, non-fibrous flesh. Highly prized in Goa for making mango desserts and eaten fresh.', 'Premium Goan Mankurad mangoes - 12 pieces, non-fibrous flesh', 849.00, 1099.00, 180, 'MAN-MAN-001', 1, 'Goan Heritage', 2400, 'dozen', 1, 0, 1, 0, 'Goa', 5, 'Fresh Mankurad Mangoes', '{"calories": 145, "serving_size": "100g", "vitamin_c": "35mg", "vitamin_a": "50mcg", "fiber": "1.2g"}', 'Store at room temperature away from direct sunlight.', 4.50, 55, 600, 9000),
(7, 'Kesar Mango (1 Dozen)', 'kesar-mango-1-dozen', 'Sweet and aromatic Kesar mangoes grown in the Konkan belt. Known for their distinct saffron-colored flesh and sweet taste. Perfect for making mango lassi, desserts, or eating fresh.', 'Sweet Kesar mangoes - 12 pieces, saffron-colored sweet flesh', 799.00, 999.00, 200, 'MAN-KES-001', 1, 'Konkan Delight', 2400, 'dozen', 0, 0, 1, 0, 'Ratnagiri', 5, 'Fresh Kesar Mangoes', '{"calories": 148, "serving_size": "100g", "vitamin_c": "32mg", "vitamin_a": "52mcg"}', 'Store at room temperature.', 4.40, 42, 500, 7000),
(8, 'Dried Mango Slices (500g)', 'dried-mango-slices-500g', 'Sun-dried Alphonso mango slices, naturally sweetened by the Konkan sun. No added sugar or preservatives. A healthy, chewy snack that retains the authentic taste of Konkan mangoes. Perfect for snacking or adding to desserts.', 'Natural sun-dried Alphonso mango slices - No added sugar', 349.00, 449.00, 400, 'MAN-DRY-001', 1, 'Konkan Bazaar Select', 500, 'pack', 0, 1, 0, 1, 'Devgad, Sindhudurg', 180, 'Dried Alphonso Mango Slices', '{"calories": 320, "serving_size": "100g", "sugar": "65g", "fiber": "3g", "carbohydrates": "78g"}', 'Store in airtight container in cool dry place.', 4.30, 35, 450, 5500),
(9, 'Raw Green Mango (1kg)', 'raw-green-mango-1kg', 'Fresh, firm raw green mangoes from Konkan farms. Perfect for making pickles, chutneys, and traditional Konkan cuisine. Sourced directly from local farmers for optimal freshness.', 'Fresh raw green mangoes for pickles and chutneys - 1kg', 199.00, 249.00, 500, 'MAN-RAW-001', 1, 'Konkan Fresh', 1000, 'kg', 0, 0, 1, 1, 'Sindhudurg', 10, 'Raw Green Mangoes', '{"calories": 60, "serving_size": "100g", "vitamin_c": "40mg", "fiber": "1.8g"}', 'Store in cool place. Refrigerate for longer shelf life.', 4.10, 28, 700, 6000),
(10, 'Totapuri Mango (1kg)', 'totapuri-mango-1kg', 'Totapuri mangoes, also known as Bangalore Mango, grown in the Konkan region. These long-shaped mangoes have a distinct tangy-sweet flavor. Excellent for making mango juice, pulp, and cooking.', 'Tangy-sweet Totapuri mangoes - 1kg for cooking and juice', 249.00, 299.00, 350, 'MAN-TOT-001', 1, 'Konkan Fresh', 1000, 'kg', 0, 0, 0, 0, 'Ratnagiri', 7, 'Fresh Totapuri Mangoes', '{"calories": 140, "serving_size": "100g", "vitamin_c": "35mg"}', 'Store at room temperature.', 4.00, 18, 350, 3500),
(11, 'Mango Squash Concentrate (750ml)', 'mango-squash-concentrate-750ml', 'Premium mango squash concentrate made from Alphonso mangoes. Just mix with water or milk for an instant refreshing drink. No artificial flavors or colors.', 'Alphonso mango squash concentrate - Makes 3L of drink', 249.00, 299.00, 600, 'MAN-SQU-001', 1, 'Konkan Delight', 750, 'bottle', 0, 0, 0, 0, 'Ratnagiri', 365, 'Mango Pulp, Sugar, Citric Acid, Preservatives (as permitted)', '{"calories": 90, "serving_size": "30ml", "sugar": "20g"}', 'Store in cool dry place. Refrigerate after opening.', 4.20, 30, 600, 4000),
(12, 'Organic Kokum Fruit (500g)', 'organic-kokum-fruit-500g', 'Dried organic kokum fruit (Garcinia indica) from the forests of Konkan. Used in traditional Konkan cuisine for making Sol Kadhi, as a natural souring agent in curries, and for its digestive and cooling properties.', 'Organic dried kokum fruit - Traditional Konkan superfood', 299.00, 379.00, 500, 'KOK-001', 1, 'Konkan Heritage', 500, 'pack', 1, 0, 0, 1, 'Sindhudurg', 365, 'Dried Kokum Fruit (Garcinia indica)', '{"calories": 45, "serving_size": "10g", "vitamin_c": "15mg", "fiber": "1g", "antioxidants": "High"}', 'Store in airtight container in cool dry place away from moisture.', 4.50, 80, 1200, 10000);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Mango Jam - Alphonso (500g)', 'mango-jam-alphonso-500g', 'Homestyle Alphonso mango jam made with real Alphonso mango pulp and minimal sugar. No artificial flavors or preservatives. Spreads beautifully on toast, parathas, or use as dessert topping.', 'Homestyle Alphonso mango jam - No artificial flavors', 199.00, 249.00, 400, 'MAN-JAM-001', 1, 'Konkan Delight', 500, 'jar', 0, 0, 0, 0, 'Devgad', 180, 'Alphonso Mango Pulp, Sugar, Pectin, Lemon Juice', '{"calories": 50, "serving_size": "20g", "sugar": "12g"}', 'Refrigerate after opening.', 4.30, 22, 400, 3000),
('Raw Mango Powder (Amchur) 200g', 'raw-mango-powder-amchur-200g', 'Pure raw mango powder made from sun-dried raw green mangoes from Konkan farms. A tangy spice essential for Indian cooking, chaats, and marinades.', 'Pure Amchur powder from Konkan raw mangoes', 129.00, 159.00, 600, 'MAN-AMC-001', 1, 'Konkan Heritage', 200, 'pack', 0, 0, 0, 1, 'Ratnagiri', 540, 'Dried Raw Mango Powder', '{"calories": 15, "serving_size": "5g", "vitamin_c": "2mg"}', 'Store in airtight container in cool dry place.', 4.10, 15, 300, 2200),
('Banana - Rajeli (1 Dozen)', 'banana-rajeli-1-dozen', 'Traditional Rajeli bananas from the Konkan region, known for their sweet taste and soft texture. Smaller than regular bananas but packed with flavor.', 'Traditional Konkan Rajeli bananas - 12 pieces', 149.00, 179.00, 300, 'FRT-BAN-001', 1, 'Konkan Fresh', 1500, 'dozen', 0, 0, 0, 1, 'Sindhudurg', 5, 'Fresh Rajeli Bananas', '{"calories": 105, "serving_size": "100g", "potassium": "358mg", "fiber": "3.1g"}', 'Store at room temperature.', 4.20, 12, 500, 3000),
('Custard Apple - Sitaphal (6 pcs)', 'custard-apple-sitaphal-6-pcs', 'Fresh custard apples (Sitaphal) from the Konkan region. These naturally sweet, creamy fruits are rich in antioxidants and vitamin C. Handpicked at peak ripeness.', 'Fresh Konkan Sitaphal - 6 pieces, naturally sweet', 349.00, 449.00, 150, 'FRT-SIT-001', 1, 'Konkan Fresh', 1200, 'pack', 0, 0, 1, 0, 'Ratnagiri', 4, 'Fresh Custard Apples', '{"calories": 101, "serving_size": "100g", "vitamin_c": "19mg", "fiber": "2.4g", "potassium": "382mg"}', 'Store at room temperature. Refrigerate once fully ripe.', 4.50, 20, 250, 4000),
('Fresh Tender Coconut (5 pcs)', 'fresh-tender-coconut-5-pcs', 'Fresh tender coconuts (Dabi) from the Konkan coast. Each coconut is full of refreshing coconut water and soft, delicious malai (coconut meat). Perfect for a natural, hydrating drink on hot days.', 'Fresh Konkan tender coconuts - 5 pieces with water and malai', 399.00, 499.00, 200, 'FRT-COC-001', 1, 'Konkan Fresh', 5000, 'pack', 0, 1, 0, 1, 'Goa', 7, 'Fresh Tender Coconuts', '{"calories": 45, "serving_size": "1 coconut water", "electrolytes": "Natural", "potassium": "600mg"}', 'Store in cool place. Consume within 7 days. Best refrigerated.', 4.60, 45, 800, 8000),
('Coconut Water - Packaged (1L)', 'coconut-water-packaged-1l', 'Pure natural coconut water sourced from young Konkan coconuts. No added sugar, no preservatives, no artificial flavors. A refreshing, electrolyte-rich natural beverage.', 'Pure Konkan coconut water - No added sugar, 1L pack', 99.00, 129.00, 800, 'FRT-COW-001', 1, 'Konkan Bazaar Select', 1000, 'carton', 0, 0, 0, 1, 'Goa', 180, 'Pure Coconut Water', '{"calories": 46, "serving_size": "240ml", "potassium": "600mg", "sodium": "250mg", "magnesium": "60mg"}', 'Store in cool dry place. Refrigerate after opening and consume within 24 hours.', 4.00, 18, 900, 4500),
('Fresh Watermelon (1 pc)', 'fresh-watermelon-1-pc', 'Fresh, juicy watermelons grown in the Konkan region. Perfectly sweet and hydrating. Ideal for summer fruit salads, juices, and desserts.', 'Fresh Konkan watermelon - Sweet and juicy', 149.00, 199.00, 100, 'FRT-WAT-001', 1, 'Konkan Fresh', 5000, 'piece', 0, 0, 0, 0, 'Sindhudurg', 10, 'Fresh Watermelon', '{"calories": 30, "serving_size": "100g", "vitamin_c": "8mg", "vitamin_a": "28mcg"}', 'Store in cool place. Refrigerate after cutting.', 3.90, 8, 300, 2000),
('Fresh Papaya - Madhu Bindu (1 pc)', 'fresh-papaya-madhu-bindu-1-pc', 'Madhu Bindu variety papaya from Konkan farms. Known for its exceptional sweetness and rich orange flesh. Rich in papain enzyme and vitamin C.', 'Sweet Madhu Bindu papaya - Rich in vitamin C', 99.00, 129.00, 150, 'FRT-PAP-001', 1, 'Konkan Fresh', 2000, 'piece', 0, 0, 0, 1, 'Ratnagiri', 7, 'Fresh Papaya', '{"calories": 43, "serving_size": "100g", "vitamin_c": "62mg", "fiber": "1.7g"}', 'Store at room temperature. Refrigerate once ripe.', 4.10, 10, 200, 1800),
('Fresh Pineapple (1 pc)', 'fresh-pineapple-1-pc', 'Sweet and tangy pineapples grown in the Konkan region. Golden yellow flesh with perfect sweetness. Great for fruit salads, desserts, or fresh juice.', 'Sweet Konkan pineapple - Golden and juicy', 89.00, 119.00, 200, 'FRT-PIN-001', 1, 'Konkan Fresh', 1500, 'piece', 0, 0, 0, 0, 'Goa', 7, 'Fresh Pineapple', '{"calories": 50, "serving_size": "100g", "vitamin_c": "48mg", "manganese": "0.9mg"}', 'Store at room temperature. Refrigerate after cutting.', 4.00, 12, 350, 2500),
('Dried Fig - Anjeer (500g)', 'dried-fig-anjeer-500g', 'Premium dried figs from the Konkan region. Naturally sun-dried, no added sugar. Rich in fiber, calcium, and antioxidants. Perfect healthy snack.', 'Natural dried Konkan figs - No added sugar', 399.00, 499.00, 300, 'FRT-FIG-001', 1, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 1, 'Sindhudurg', 365, 'Dried Figs (Ficus carica)', '{"calories": 249, "serving_size": "100g", "fiber": "9.8g", "calcium": "162mg", "iron": "2mg"}', 'Store in airtight container in cool dry place.', 4.30, 15, 200, 2800),
('Organic Jamun Fruit (500g)', 'organic-jamun-fruit-500g', 'Fresh organic Jamun (Java Plum) fruits from the Konkan region. These purple-black fruits are known for their unique sweet-tart flavor and health benefits. Rich in iron, vitamin C, and antioxidants.', 'Organic fresh Jamun fruit - Rich in iron and antioxidants', 249.00, 299.00, 100, 'FRT-JAM-001', 1, 'Konkan Heritage', 500, 'pack', 0, 0, 1, 1, 'Ratnagiri', 3, 'Fresh Jamun Fruits', '{"calories": 62, "serving_size": "100g", "vitamin_c": "18mg", "iron": "1.4mg", "antioxidants": "High"}', 'Store in refrigerator. Consume within 2-3 days.', 4.40, 18, 180, 3200);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Sundried Bombay Duck - Bombil (500g)', 'sundried-bombay-duck-bombil-500g', 'Premium sundried Bombay Duck (Bombil) from the coastal villages of Ratnagiri. Traditional sun-drying process preserves the authentic flavor. A coastal delicacy, perfect for frying or adding to curries.', 'Traditional sundried Bombil - Coastal Konkan delicacy', 449.00, 549.00, 200, 'SFD-BOM-001', 2, 'Konkan Heritage', 500, 'pack', 1, 1, 0, 0, 'Ratnagiri', 180, 'Dried Bombay Duck Fish, Salt', '{"calories": 250, "serving_size": "100g", "protein": "50g", "fat": "5g", "omega_3": "2.5g"}', 'Store in airtight container in cool dry place. No refrigeration needed.', 4.60, 90, 2000, 22000),
('Sundried Prawns - Sungta (500g)', 'sundried-prawns-sungta-500g', 'Traditional sundried prawns (Sungta) from the Konkan coast. Medium-sized prawns dried using age-old coastal techniques. Intense seafood flavor perfect for Konkan curries and stir-fries.', 'Traditional sundried prawns - Authentic Konkan Sungta', 599.00, 749.00, 150, 'SFD-PRW-001', 2, 'Konkan Heritage', 500, 'pack', 1, 1, 0, 0, 'Sindhudurg', 180, 'Dried Prawns, Salt', '{"calories": 280, "serving_size": "100g", "protein": "55g", "fat": "6g", "calcium": "150mg"}', 'Store in airtight container. Keep away from moisture.', 4.50, 65, 1500, 16000),
('Sundried Mackerel - Bangda (500g)', 'sundried-mackerel-bangda-500g', 'Sundried mackerel (Bangda) prepared in traditional Konkan style using fresh catch from the Arabian Sea. Rich in omega-3 fatty acids and intense coastal flavor.', 'Traditional sundried Bangda mackerel - Omega-3 rich', 349.00, 449.00, 180, 'SFD-MAC-001', 2, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 0, 'Goa', 180, 'Dried Mackerel, Salt', '{"calories": 260, "serving_size": "100g", "protein": "48g", "omega_3": "3g", "vitamin_d": "20mcg"}', 'Store in cool dry place in airtight container.', 4.30, 35, 800, 9000),
('Sundried Shrimp - Kolambi (250g)', 'sundried-shrimp-kolambi-250g', 'Small sundried shrimp (Kolambi) from Konkan coast. These tiny flavor bombs are essential Konkan pantry items. Used in Konkan-style chutneys, curries, and rice dishes.', 'Traditional sundried small shrimp - Kolambi, 250g', 299.00, 379.00, 300, 'SFD-SHR-001', 2, 'Konkan Heritage', 250, 'pack', 0, 1, 0, 0, 'Ratnagiri', 180, 'Dried Small Shrimp, Salt', '{"calories": 240, "serving_size": "100g", "protein": "50g", "calcium": "200mg"}', 'Store in airtight container in cool dry place.', 4.40, 40, 900, 8500),
('Fresh King Prawns - Raw (500g)', 'fresh-king-prawns-raw-500g', 'Fresh large King Prawns (Kolambi) caught from the Arabian Sea off the Konkan coast. Cleaned, deveined, and flash-frozen for freshness. Perfect for tandoori, curry, or garlic butter preparation.', 'Fresh King Prawns - Large size, cleaned, 500g', 799.00, 999.00, 80, 'SFD-KPR-001', 2, 'Konkan Fresh', 500, 'pack', 1, 0, 0, 0, 'Goa', 30, 'Fresh King Prawns', '{"calories": 120, "serving_size": "100g", "protein": "24g", "fat": "1.5g", "cholesterol": "180mg", "omega_3": "1.8g"}', 'Keep frozen. Thaw in refrigerator before cooking.', 4.60, 38, 600, 7500),
('Fresh Pomfret - Whole (2 pcs)', 'fresh-pomfret-whole-2-pcs', 'Fresh whole Pomfret (Paplet) from Konkan waters. Known for its delicate white flesh and mild sweet flavor. Perfect for Konkan-style fish curry, frying, or steaming.', 'Fresh Pomfret - 2 whole pieces, mild sweet flavor', 599.00, 749.00, 60, 'SFD-POM-001', 2, 'Konkan Fresh', 1000, 'pack', 1, 0, 0, 0, 'Ratnagiri', 3, 'Fresh Pomfret Fish', '{"calories": 110, "serving_size": "100g", "protein": "20g", "fat": "3g", "omega_3": "1.5g"}', 'Keep refrigerated. Cook within 24-48 hours.', 4.50, 30, 450, 6500),
('Fresh Bangda Mackerel (500g)', 'fresh-bangda-mackerel-500g', 'Fresh Indian Mackerel (Bangda) from the Arabian Sea. Rich, flavorful fish perfect for Konkan curries and fried preparations. Known for its high omega-3 content.', 'Fresh Bangda Mackerel - 500g, rich in omega-3', 249.00, 299.00, 100, 'SFD-BNG-001', 2, 'Konkan Fresh', 500, 'pack', 0, 1, 0, 0, 'Sindhudurg', 3, 'Fresh Indian Mackerel', '{"calories": 160, "serving_size": "100g", "protein": "19g", "fat": "9g", "omega_3": "2.6g"}', 'Keep refrigerated. Cook within 24 hours.', 4.30, 25, 800, 5500),
('Fresh Surmai - Kingfish Steaks (500g)', 'fresh-surmai-kingfish-steaks-500g', 'Fresh Kingfish (Surmai) steaks from the Konkan coast. Firm, meaty flesh that holds up well in curries and grilling. A favorite in Goan and Malvani cuisine.', 'Fresh Surmai Kingfish steaks - 500g, firm meaty flesh', 649.00, 799.00, 70, 'SFD-SUR-001', 2, 'Konkan Fresh', 500, 'pack', 0, 0, 0, 0, 'Goa', 3, 'Fresh Kingfish Steaks', '{"calories": 130, "serving_size": "100g", "protein": "22g", "fat": "4g", "omega_3": "2g"}', 'Keep refrigerated. Cook within 24 hours.', 4.40, 20, 300, 4500),
('Fish Curry Masala - Malvani (200g)', 'fish-curry-masala-malvani-200g', 'Authentic Malvani fish curry masala blend made with traditional Konkan spices. No artificial flavors or colors. Just add coconut milk and fresh fish for an authentic Konkan fish curry.', 'Authentic Malvani fish curry masala - 200g pack', 129.00, 159.00, 500, 'SFD-MAS-001', 2, 'Konkan Heritage', 200, 'pack', 0, 1, 0, 1, 'Ratnagiri', 540, 'Red Chili, Coriander, Cumin, Pepper, Turmeric, Garlic, Onion, Coconut, Tamarind', '{"calories": 25, "serving_size": "10g"}', 'Store in airtight container in cool dry place.', 4.50, 55, 1500, 8000),
('Prawn Pickle - Kolambi Lonche (400g)', 'prawn-pickle-kolambi-lonche-400g', 'Traditional Konkan style prawn pickle made with sundried prawns and authentic spices. A coastal delicacy that pairs perfectly with steamed rice and dal.', 'Traditional Konkan prawn pickle - Kolambi Lonche', 249.00, 299.00, 250, 'SFD-PPK-001', 2, 'Konkan Heritage', 400, 'jar', 0, 0, 0, 0, 'Sindhudurg', 365, 'Dried Prawns, Mustard Oil, Red Chili, Turmeric, Garlic, Salt, Vinegar', '{"calories": 60, "serving_size": "20g", "protein": "4g"}', 'Store in cool dry place. Refrigerate after opening.', 4.40, 28, 600, 4500),
('Bangda Fry Masala (100g)', 'bangda-fry-masala-100g', 'Special spice blend for Konkan-style Bangda (Mackerel) fry. Made with traditional Konkan spices and grated coconut. Gives an authentic coastal flavor to fried fish.', 'Special Bangda fry masala mix - 100g', 79.00, 99.00, 600, 'SFD-BFM-001', 2, 'Konkan Heritage', 100, 'pack', 0, 0, 0, 0, 'Ratnagiri', 365, 'Red Chili, Coriander, Cumin, Turmeric, Garlic, Ginger, Coconut', '{"calories": 20, "serving_size": "10g"}', 'Store in cool dry place.', 4.10, 15, 400, 2500),
('Dried Anchovies - Kati (250g)', 'dried-anchovies-kati-250g', 'Traditional sundried anchovies (Kati) from the Konkan coast. Small, intensely flavorful dried fish used in Konkan chutneys, curries, and as a side dish with rice.', 'Traditional sundried anchovies - Kati, 250g', 199.00, 249.00, 350, 'SFD-ANC-001', 2, 'Konkan Heritage', 250, 'pack', 0, 0, 0, 0, 'Goa', 180, 'Dried Anchovies, Salt', '{"calories": 220, "serving_size": "100g", "protein": "45g", "calcium": "350mg"}', 'Store in airtight container in cool dry place.', 4.20, 20, 500, 3500),
('Goan Recheado Masala Paste (250g)', 'goan-recheado-masala-paste-250g', 'Authentic Goan Recheado masala paste made with traditional Goan spices, red chilies, vinegar, and garlic. Perfect for stuffing mackerel, pomfret, or prawns before frying.', 'Authentic Goan Recheado masala - 250g, for stuffed fish', 149.00, 189.00, 400, 'SFD-REC-001', 2, 'Goan Heritage', 250, 'jar', 0, 0, 0, 0, 'Goa', 180, 'Red Chili, Garlic, Cumin, Pepper, Cloves, Cinnamon, Vinegar, Salt', '{"calories": 30, "serving_size": "15g"}', 'Refrigerate after opening.', 4.50, 32, 700, 5000);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Cold Pressed Coconut Oil (1L)', 'cold-pressed-coconut-oil-1l', 'Pure cold-pressed virgin coconut oil made from fresh Konkan coconuts. No heat processing, no chemicals, no preservatives. Retains the natural aroma, flavor, and nutrients of fresh coconut. Perfect for cooking, hair care, and skin care.', 'Pure cold-pressed virgin coconut oil - 1L, no chemicals', 449.00, 549.00, 400, 'COC-OIL-001', 3, 'Konkan Heritage', 1000, 'bottle', 1, 1, 0, 1, 'Sindhudurg', 540, '100% Cold Pressed Virgin Coconut Oil', '{"calories": 120, "serving_size": "15ml", "fat": "14g", "saturated_fat": "12g"}', 'Store in cool dry place away from direct sunlight. Solidifies in winter - natural.', 4.70, 150, 3000, 30000),
('Virgin Coconut Oil - Organic (500ml)', 'virgin-coconut-oil-organic-500ml', 'Organic certified virgin coconut oil extracted from fresh organic coconuts grown in Konkan. Cold-pressed and unrefined. Rich in medium-chain triglycerides (MCTs) and lauric acid.', 'Organic virgin coconut oil - Cold pressed, 500ml', 299.00, 379.00, 500, 'COC-OIL-002', 3, 'Konkan Bazaar Select', 500, 'bottle', 1, 1, 0, 1, 'Ratnagiri', 540, '100% Organic Virgin Coconut Oil', '{"calories": 120, "serving_size": "15ml", "mct": "6g", "lauric_acid": "5g"}', 'Store in cool dark place. Natural coconut aroma may vary.', 4.60, 85, 2500, 22000),
('Desiccated Coconut Powder (500g)', 'desiccated-coconut-powder-500g', 'Fine desiccated coconut powder made from fresh, mature Konkan coconuts. Dried using gentle heat to preserve natural flavor and nutrients. Perfect for cooking, baking, and traditional Konkan recipes.', 'Fine desiccated coconut powder - 500g, natural', 199.00, 249.00, 600, 'COC-DES-001', 3, 'Konkan Fresh', 500, 'pack', 0, 0, 0, 0, 'Goa', 365, '100% Desiccated Coconut', '{"calories": 135, "serving_size": "30g", "fiber": "5g", "fat": "12g"}', 'Store in airtight container in cool dry place.', 4.20, 30, 800, 5000),
('Coconut Milk - Fresh (500ml)', 'coconut-milk-fresh-500ml', 'Fresh coconut milk extracted from mature Konkan coconuts. Rich and creamy with no added preservatives. Essential for authentic Konkan curries, sol kadhi, and desserts.', 'Fresh creamy coconut milk - 500ml, no preservatives', 149.00, 179.00, 300, 'COC-MLK-001', 3, 'Konkan Fresh', 500, 'carton', 0, 1, 0, 0, 'Sindhudurg', 7, 'Fresh Coconut Milk, Water, Citric Acid', '{"calories": 45, "serving_size": "30ml", "fat": "4.5g"}', 'Refrigerate. Shake well before use. Consume within 5 days of opening.', 4.30, 25, 900, 4200),
('Coconut Cream - Thick (200ml)', 'coconut-cream-thick-200ml', 'Thick coconut cream extracted from the first pressing of fresh Konkan coconuts. Extra rich and creamy. Perfect for rich curries, desserts, and making coconut-based sauces.', 'Thick coconut cream - 200ml, first pressing', 129.00, 159.00, 400, 'COC-CRM-001', 3, 'Konkan Fresh', 200, 'carton', 0, 0, 0, 0, 'Goa', 10, 'Fresh Coconut Cream', '{"calories": 55, "serving_size": "30ml", "fat": "5.5g"}', 'Refrigerate. Consume within 5 days of opening.', 4.10, 15, 400, 2800),
('Dry Coconut - Copra (500g)', 'dry-coconut-copra-500g', 'Sun-dried coconut pieces (Copra) from mature Konkan coconuts. Used in traditional Konkan cooking for making chutneys, curries, and sweets. Also used for extracting coconut oil.', 'Sun-dried coconut pieces - Copra, 500g', 249.00, 299.00, 500, 'COC-COP-001', 3, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 0, 'Ratnagiri', 365, 'Dried Coconut Pieces', '{"calories": 140, "serving_size": "30g", "fiber": "4g", "fat": "13g"}', 'Store in airtight container in cool dry place.', 4.00, 10, 300, 2500),
('Coconut Chips - Roasted (200g)', 'coconut-chips-roasted-200g', 'Roasted coconut chips made from fresh Konkan coconuts. Lightly salted and roasted to golden perfection. A healthy, crunchy snack rich in fiber and healthy fats.', 'Roasted coconut chips - 200g, healthy crunchy snack', 149.00, 189.00, 400, 'COC-CHP-001', 3, 'Konkan Bazaar Select', 200, 'pack', 0, 0, 0, 0, 'Goa', 120, 'Fresh Coconut, Salt', '{"calories": 180, "serving_size": "30g", "fiber": "5g", "fat": "16g"}', 'Store in airtight container in cool dry place.', 4.30, 18, 500, 3200),
('Coconut Vinegar (500ml)', 'coconut-vinegar-500ml', 'Natural coconut vinegar made from fermented coconut sap. Mild and fruity with less acidity than regular vinegar. Used in Konkan cuisine for pickling and marinades.', 'Natural coconut vinegar - 500ml, mild and fruity', 129.00, 159.00, 300, 'COC-VIN-001', 3, 'Konkan Heritage', 500, 'bottle', 0, 0, 0, 1, 'Sindhudurg', 730, 'Fermented Coconut Sap', '{"calories": 5, "serving_size": "15ml"}', 'Store in cool dry place away from direct sunlight.', 4.00, 10, 200, 1500),
('Coconut Sugar - Organic (500g)', 'coconut-sugar-organic-500g', 'Organic coconut sugar made from the sap of Konkan coconut palm flowers. Low glycemic index, rich in minerals, and a natural alternative to refined sugar. Caramel-like flavor.', 'Organic coconut sugar - 500g, low glycemic', 299.00, 379.00, 350, 'COC-SGR-001', 3, 'Konkan Bazaar Select', 500, 'pack', 0, 0, 0, 1, 'Goa', 540, '100% Organic Coconut Sugar', '{"calories": 45, "serving_size": "10g", "glycemic_index": "35", "potassium": "130mg"}', 'Store in airtight container in cool dry place.', 4.20, 15, 350, 2800),
('Coconut Laddu (200g)', 'coconut-laddu-200g', 'Traditional Konkan-style coconut laddus made with fresh grated coconut and pure jaggery. No preservatives, no artificial flavors. A beloved festive sweet from the Konkan region.', 'Traditional coconut laddus - 200g, made with jaggery', 149.00, 179.00, 250, 'COC-LAD-001', 3, 'Konkan Heritage', 200, 'pack', 0, 0, 0, 0, 'Ratnagiri', 15, 'Fresh Coconut, Jaggery, Cardamom', '{"calories": 120, "serving_size": "30g", "sugar": "12g", "fiber": "2g"}', 'Store in cool place. Refrigerate for longer shelf life.', 4.40, 22, 450, 3000),
('Coconut Barfi (250g)', 'coconut-barfi-250g', 'Soft and delicious coconut barfi made with fresh Konkan coconut and milk. A popular Konkan sweet, perfect for festivals and celebrations.', 'Soft coconut barfi - 250g, traditional Konkan sweet', 179.00, 219.00, 200, 'COC-BRF-001', 3, 'Konkan Heritage', 250, 'pack', 0, 0, 0, 0, 'Goa', 12, 'Fresh Coconut, Milk, Sugar, Cardamom, Ghee', '{"calories": 140, "serving_size": "30g", "sugar": "15g"}', 'Store in cool place or refrigerate.', 4.30, 15, 300, 2200);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Indrayani Rice - Premium (5kg)', 'indrayani-rice-premium-5kg', 'Premium Indrayani rice from the foothills of the Sahyadri mountains in Konkan. Known for its distinct aroma, delicate texture, and excellent taste. Traditionally used for making fragrant rice dishes and bhog.', 'Premium Indrayani rice - 5kg, aromatic Konkan rice', 749.00, 949.00, 300, 'RIC-IND-001', 4, 'Konkan Heritage', 5000, 'bag', 1, 1, 0, 1, 'Ratnagiri', 365, 'Premium Indrayani Rice', '{"calories": 130, "serving_size": "100g cooked", "carbohydrates": "28g", "protein": "2.5g", "fiber": "0.4g"}', 'Store in airtight container in cool dry place.', 4.70, 110, 2500, 20000),
('Ambemohar Rice (5kg)', 'ambemohar-rice-5kg', 'Fragrant Ambemohar rice, known as the "mango blossom rice" for its distinct aroma reminiscent of mango blossoms. Grown in the Konkan region, this rice is prized for its unique fragrance, light texture, and delicate flavor.', 'Fragrant Ambemohar rice - 5kg, mango blossom aroma', 899.00, 1099.00, 250, 'RIC-AMB-001', 4, 'Konkan Heritage', 5000, 'bag', 1, 1, 0, 1, 'Sindhudurg', 365, 'Premium Ambemohar Rice', '{"calories": 130, "serving_size": "100g cooked", "carbohydrates": "28g", "protein": "2.5g", "fiber": "0.3g"}', 'Store in airtight container in cool dry place away from strong odors.', 4.60, 85, 2000, 18000),
('Red Rice - Organic (5kg)', 'red-rice-organic-5kg', 'Organic red rice from the Konkan region, unpolished and packed with nutrients. Rich in fiber, iron, and antioxidants. The natural red bran layer gives it a nutty flavor and chewy texture. A healthy alternative to white rice.', 'Organic Red Rice - 5kg, unpolished, nutrient-rich', 649.00, 799.00, 200, 'RIC-RED-001', 4, 'Konkan Bazaar Select', 5000, 'bag', 1, 0, 0, 1, 'Goa', 365, 'Organic Unpolished Red Rice', '{"calories": 120, "serving_size": "100g cooked", "fiber": "3g", "iron": "1.5mg", "magnesium": "45mg"}', 'Store in airtight container in cool dry place.', 4.50, 55, 1500, 14000),
('Govind Bhog Rice (5kg)', 'govind-bhog-rice-5kg', 'Premium Govind Bhog rice from the Konkan region. Known for its sweet aroma and small, short grains. Traditionally used in Bengali cuisine and for making khichdi and payesh.', 'Aromatic Govind Bhog rice - 5kg, small sweet grains', 849.00, 1049.00, 150, 'RIC-GOV-001', 4, 'Konkan Heritage', 5000, 'bag', 0, 0, 0, 0, 'Ratnagiri', 365, 'Premium Govind Bhog Rice', '{"calories": 130, "serving_size": "100g cooked", "carbohydrates": "28g"}', 'Store in airtight container.', 4.30, 20, 400, 5000),
('Basmati Rice - Konkan Gold (5kg)', 'basmati-rice-konkan-gold-5kg', 'Long grain Basmati rice grown in the Konkan region. Fragrant, fluffy, and perfect for biryani and pulao. Each grain remains separate after cooking.', 'Premium Konkan Basmati rice - 5kg, long grain', 699.00, 899.00, 500, 'RIC-BAS-001', 4, 'Konkan Bazaar Select', 5000, 'bag', 0, 1, 0, 0, 'Sindhudurg', 365, 'Premium Basmati Rice', '{"calories": 130, "serving_size": "100g cooked", "carbohydrates": "28g", "protein": "2.6g"}', 'Store in airtight container in cool dry place.', 4.20, 35, 1200, 8000),
('Brown Rice - Organic (5kg)', 'brown-rice-organic-5kg', 'Organic brown rice from the Konkan region. Minimally processed to retain the bran layer and germ. High in fiber, vitamins, and minerals. A healthy whole grain choice.', 'Organic brown rice - 5kg, high fiber whole grain', 549.00, 699.00, 250, 'RIC-BRN-001', 4, 'Konkan Bazaar Select', 5000, 'bag', 0, 0, 0, 1, 'Goa', 365, 'Organic Brown Rice', '{"calories": 110, "serving_size": "100g cooked", "fiber": "3.5g", "protein": "2.5g", "magnesium": "40mg"}', 'Store in airtight container in cool dry place. Refrigerate for longer shelf life.', 4.30, 18, 500, 4500),
('Kolam Rice (5kg)', 'kolam-rice-5kg', 'Premium Kolam rice from the Konkan region. Short-grain, slightly sticky rice known for its sweet taste and soft texture. Perfect for daily consumption and making rice dishes.', 'Soft sweet Kolam rice - 5kg, daily cooking', 599.00, 749.00, 350, 'RIC-KOL-001', 4, 'Konkan Fresh', 5000, 'bag', 0, 0, 0, 0, 'Ratnagiri', 365, 'Premium Kolam Rice', '{"calories": 130, "serving_size": "100g cooked", "carbohydrates": "29g", "protein": "2.4g"}', 'Store in airtight container.', 4.10, 15, 600, 3500),
('Rice Flakes - Poha (1kg)', 'rice-flakes-poha-1kg', 'Traditional Konkan-style poha (rice flakes) made from premium Indrayani rice. Thick, flat rice flakes perfect for making the classic Konkan breakfast dish - Kanda Poha.', 'Traditional Indrayani poha - 1kg, thick flakes', 149.00, 179.00, 600, 'RIC-POH-001', 4, 'Konkan Heritage', 1000, 'pack', 0, 1, 0, 0, 'Sindhudurg', 180, 'Rice Flakes (Poha)', '{"calories": 110, "serving_size": "50g", "carbohydrates": "24g", "fiber": "0.5g"}', 'Store in airtight container in cool dry place.', 4.30, 25, 1000, 5000),
('Puffed Rice - Murmura (500g)', 'puffed-rice-murmura-500g', 'Traditional puffed rice (Murmura) made from premium Konkan rice. Light, crispy, and perfectly puffed. Used for making bhel puri, chivda, and other traditional Konkan snacks.', 'Crispy puffed rice - 500g, for bhel and chivda', 79.00, 99.00, 800, 'RIC-MUR-001', 4, 'Konkan Fresh', 500, 'pack', 0, 0, 0, 0, 'Ratnagiri', 365, 'Puffed Rice', '{"calories": 50, "serving_size": "20g", "carbohydrates": "11g"}', 'Store in airtight container to maintain crispiness.', 4.00, 10, 400, 2500),
('Rice Flour - Organic (2kg)', 'rice-flour-organic-2kg', 'Organic rice flour made from Konkan-grown rice. Finely ground and perfectly textured for making traditional Konkan dishes like pathrode, ambil, and savoury pancakes.', 'Organic rice flour - 2kg, fine ground', 199.00, 249.00, 400, 'RIC-FLR-001', 4, 'Konkan Heritage', 2000, 'pack', 0, 0, 0, 1, 'Goa', 365, 'Organic Rice Flour', '{"calories": 110, "serving_size": "30g", "carbohydrates": "25g", "fiber": "1g"}', 'Store in airtight container in cool dry place.', 4.10, 12, 350, 2000);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Sol Kadhi Concentrate (750ml)', 'sol-kadhi-concentrate-750ml', 'Authentic Sol Kadhi concentrate made from kokum and fresh coconut milk. A traditional Konkan digestive and cooling beverage. Just add chilled water and stir for an instant refreshing drink.', 'Authentic Sol Kadhi concentrate - 750ml, refreshing Konkan drink', 249.00, 299.00, 400, 'KOK-SOL-001', 5, 'Konkan Heritage', 750, 'bottle', 1, 1, 0, 0, 'Sindhudurg', 365, 'Kokum Extract, Coconut Milk, Garlic, Green Chili, Cumin, Salt', '{"calories": 35, "serving_size": "100ml prepared", "antioxidants": "High"}', 'Store in cool dry place. Refrigerate after opening.', 4.60, 95, 2500, 20000),
('Kokum Juice - Ready to Drink (1L)', 'kokum-juice-ready-to-drink-1l', 'Refreshing kokum juice made from real kokum fruit. A traditional Konkan thirst-quencher with digestive benefits. No artificial colors or flavors.', 'Refreshing kokum juice - 1L, no artificial colors', 179.00, 219.00, 500, 'KOK-JUS-001', 5, 'Konkan Delight', 1000, 'carton', 1, 1, 0, 0, 'Ratnagiri', 180, 'Kokum Juice, Water, Sugar, Salt, Cumin', '{"calories": 60, "serving_size": "200ml", "vitamin_c": "10mg", "antioxidants": "High"}', 'Refrigerate after opening. Consume within 5 days.', 4.50, 60, 2000, 15000),
('Dried Kokum Rind (250g)', 'dried-kokum-rind-250g', 'Premium dried kokum rind from the forests of Konkan. Dark purple, rich in antioxidants and hydroxycitric acid (HCA). Used as a natural souring agent in curries and for making Sol Kadhi.', 'Premium dried kokum rind - 250g, natural souring agent', 199.00, 249.00, 600, 'KOK-DRY-001', 5, 'Konkan Heritage', 250, 'pack', 0, 1, 0, 1, 'Sindhudurg', 540, 'Dried Kokum Rind (Garcinia indica)', '{"calories": 40, "serving_size": "10g", "vitamin_c": "15mg", "antioxidants": "Very High"}', 'Store in airtight container in cool dry place.', 4.50, 45, 1800, 10000),
('Kokum Syrup - Concentrate (500ml)', 'kokum-syrup-concentrate-500ml', 'Rich kokum syrup concentrate made from authentic Konkan kokum. Mix with chilled water or soda for an instant refreshing drink. Perfect summer beverage.', 'Kokum syrup concentrate - 500ml, makes 5L drink', 199.00, 239.00, 350, 'KOK-SYR-001', 5, 'Konkan Delight', 500, 'bottle', 0, 0, 0, 0, 'Ratnagiri', 365, 'Kokum Extract, Sugar, Salt, Cumin, Preservatives (as permitted)', '{"calories": 50, "serving_size": "30ml", "sugar": "12g"}', 'Store in cool dry place. Refrigerate after opening.', 4.20, 20, 600, 3500),
('Tamarind Concentrate (500ml)', 'tamarind-concentrate-500ml', 'Pure tamarind concentrate from premium Konkan tamarind. Rich, tangy, and ready to use. Perfect for curries, chutneys, and traditional Konkan recipes.', 'Pure tamarind concentrate - 500ml, ready to use', 149.00, 179.00, 400, 'KOK-TAM-001', 5, 'Konkan Heritage', 500, 'bottle', 0, 0, 0, 0, 'Goa', 540, 'Tamarind Extract, Water, Preservative (as permitted)', '{"calories": 10, "serving_size": "15ml"}', 'Store in cool dry place.', 4.10, 15, 400, 2500),
('Fresh Lime Juice (1L)', 'fresh-lime-juice-1l', 'Freshly squeezed lime juice from limes grown in the Konkan region. No added water or sugar. Perfect for making limeade, cocktails, and cooking.', 'Fresh squeezed lime juice - 1L, no added water', 199.00, 249.00, 250, 'KOK-LIM-001', 5, 'Konkan Fresh', 1000, 'carton', 0, 0, 0, 0, 'Ratnagiri', 15, 'Fresh Lime Juice', '{"calories": 25, "serving_size": "30ml", "vitamin_c": "15mg"}', 'Refrigerate. Consume within 10 days of opening.', 4.00, 8, 300, 2000),
('Sugarcane Juice - Packaged (1L)', 'sugarcane-juice-packaged-1l', 'Fresh sugarcane juice from Konkan-grown sugarcane. Naturally sweet and refreshing. No added sugar or preservatives. Rich in iron and antioxidants.', 'Fresh sugarcane juice - 1L, natural sweetness', 99.00, 129.00, 300, 'KOK-SUG-001', 5, 'Konkan Fresh', 1000, 'carton', 0, 0, 0, 0, 'Sindhudurg', 45, 'Pure Sugarcane Juice', '{"calories": 110, "serving_size": "200ml", "sugar": "24g", "iron": "1.5mg"}', 'Refrigerate. Consume within 3 days of opening.', 4.00, 10, 400, 2200),
('Buttermilk Masala - Chaas Mix (200g)', 'buttermilk-masala-chaas-mix-200g', 'Traditional Konkan-style buttermilk masala mix. A blend of roasted cumin, black salt, mint, and other spices. Just add to fresh buttermilk for an instant refreshing chaas.', 'Konkan-style chaas masala - 200g, instant mix', 79.00, 99.00, 500, 'KOK-CHA-001', 5, 'Konkan Heritage', 200, 'pack', 0, 0, 0, 0, 'Goa', 540, 'Cumin, Black Salt, Mint, Ginger, Green Chili, Coriander, Salt', '{"calories": 5, "serving_size": "5g"}', 'Store in airtight container in cool dry place.', 4.10, 12, 500, 2200),
('Aamras - Mango Pulp (500g)', 'aamras-mango-pulp-500g', 'Pure Alphonso mango pulp (Aamras) from Devgad mangoes. Rich, thick, and naturally sweet. No added sugar or preservatives. Perfect with puris or as dessert topping.', 'Pure Alphonso aamras - 500g, no added sugar', 349.00, 449.00, 250, 'KOK-AAM-001', 5, 'Konkan Bazaar Select', 500, 'jar', 0, 0, 1, 0, 'Devgad', 365, '100% Alphonso Mango Pulp', '{"calories": 120, "serving_size": "100g", "sugar": "28g"}', 'Store in cool place. Refrigerate after opening.', 4.50, 30, 600, 5000),
('Coconut Water - Tender (1L Tetra)', 'coconut-water-tender-1l-tetra', 'Pure tender coconut water from young Konkan coconuts. Packed in tetra pack to preserve natural electrolytes and freshness. No added sugar.', 'Pure tender coconut water - 1L, natural electrolytes', 120.00, 149.00, 600, 'KOK-CWT-001', 5, 'Konkan Bazaar Select', 1000, 'carton', 0, 0, 0, 0, 'Goa', 180, 'Pure Tender Coconut Water', '{"calories": 45, "serving_size": "240ml", "potassium": "500mg", "sodium": "200mg"}', 'Store at room temperature. Refrigerate for best taste.', 4.10, 18, 700, 3500);
