('Mango Pickle - Traditional (500g)', 'mango-pickle-traditional-500g', 'Traditional Konkan-style mango pickle made from raw green mangoes and a special blend of spices. Aged to perfection for authentic taste. No artificial colors or preservatives.', 'Traditional Konkan mango pickle - 500g, aged recipe', 199.00, 249.00, 500, 'PIC-MAN-001', 6, 'Konkan Heritage', 500, 'jar', 1, 1, 0, 0, 'Ratnagiri', 540, 'Raw Mango, Mustard Oil, Red Chili, Turmeric, Fenugreek, Salt, Vinegar', '{"calories": 25, "serving_size": "15g"}', 'Store in cool dry place. Use dry spoon always.', 4.50, 80, 2000, 12000),
('Lime Pickle - Spicy (500g)', 'lime-pickle-spicy-500g', 'Spicy Konkan-style lime pickle made with fresh limes and traditional spices. Cured to perfection with a perfect balance of tangy, spicy, and salty flavors.', 'Spicy lime pickle - 500g, traditional Konkan style', 179.00, 219.00, 400, 'PIC-LIM-001', 6, 'Konkan Heritage', 500, 'jar', 0, 1, 0, 0, 'Sindhudurg', 540, 'Lime, Red Chili, Mustard Seeds, Fenugreek, Turmeric, Salt, Oil', '{"calories": 20, "serving_size": "15g"}', 'Store in cool dry place.', 4.40, 35, 1000, 6000),
('Mixed Vegetable Pickle (500g)', 'mixed-vegetable-pickle-500g', 'Konkan-style mixed vegetable pickle with carrots, cauliflower, turnip, and green mangoes. A colorful and flavorful pickle made with traditional spice blend.', 'Mixed vegetable pickle - 500g, Konkan style', 199.00, 249.00, 350, 'PIC-MIX-001', 6, 'Konkan Heritage', 500, 'jar', 0, 0, 0, 0, 'Goa', 540, 'Carrots, Cauliflower, Turnip, Green Mango, Mustard Oil, Spices, Salt', '{"calories": 22, "serving_size": "15g"}', 'Store in cool dry place.', 4.20, 18, 500, 3200),
('Garlic Pickle (500g)', 'garlic-pickle-500g', 'Traditional Konkan garlic pickle made with whole garlic cloves and authentic spices. A pungent, flavorful pickle that is a staple in Konkan households.', 'Garlic pickle - 500g, whole cloves, Konkan style', 249.00, 299.00, 300, 'PIC-GAR-001', 6, 'Konkan Heritage', 500, 'jar', 0, 0, 0, 0, 'Ratnagiri', 540, 'Garlic Cloves, Mustard Oil, Red Chili, Vinegar, Salt, Spices', '{"calories": 30, "serving_size": "15g"}', 'Store in cool dry place away from sunlight.', 4.30, 20, 400, 2800),
('Tendli (Ivy Gourd) Pickle (500g)', 'tendli-ivy-gourd-pickle-500g', 'Traditional Konkan-style Tendli (ivy gourd) pickle. Crispy and tangy with authentic Konkan spices. A unique coastal specialty.', 'Konkan-style Tendli pickle - 500g, crispy and tangy', 219.00, 269.00, 250, 'PIC-TEN-001', 6, 'Konkan Heritage', 500, 'jar', 0, 0, 0, 0, 'Sindhudurg', 540, 'Ivy Gourd, Mustard Oil, Red Chili, Turmeric, Mustard Seeds, Salt', '{"calories": 20, "serving_size": "15g"}', 'Store in cool dry place.', 4.10, 12, 300, 2500),
('Coconut Chutney Powder (200g)', 'coconut-chutney-powder-200g', 'Instant coconut chutney powder made from roasted coconut and traditional Konkan spices. Just mix with water or yogurt for instant chutney. Perfect accompaniment for dosa, idli, and rice.', 'Instant coconut chutney powder - 200g, mix and serve', 99.00, 129.00, 600, 'PIC-COC-001', 6, 'Konkan Heritage', 200, 'pack', 0, 1, 0, 0, 'Goa', 365, 'Roasted Coconut, Red Chili, Cumin, Coriander, Tamarind, Salt', '{"calories": 15, "serving_size": "10g"}', 'Store in airtight container in cool dry place.', 4.30, 25, 800, 4500),
('Mint Chutney - Instant Mix (200g)', 'mint-chutney-instant-mix-200g', 'Instant mint chutney mix with authentic Konkan flavors. Blend of dried mint, green chili, and traditional spices. Just add water and fresh mint for delicious chutney.', 'Instant mint chutney mix - 200g, Konkan style', 89.00, 109.00, 500, 'PIC-MIN-001', 6, 'Konkan Heritage', 200, 'pack', 0, 0, 0, 0, 'Ratnagiri', 365, 'Dried Mint, Green Chili, Cumin, Coriander, Salt, Citric Acid', '{"calories": 5, "serving_size": "5g"}', 'Store in airtight container.', 4.00, 10, 350, 2000),
('Dry Chutney - Shenga (Peanut) 250g', 'dry-chutney-shenga-peanut-250g', 'Konkan-style dry peanut chutney (Shenga Chutney). Roasted peanuts with red chili, garlic, and coconut. Perfect side dish for bhakri, rice, or roti.', 'Konkan-style peanut dry chutney - 250g', 129.00, 159.00, 400, 'PIC-PNT-001', 6, 'Konkan Heritage', 250, 'pack', 0, 0, 0, 0, 'Sindhudurg', 120, 'Roasted Peanuts, Red Chili, Garlic, Coconut, Salt', '{"calories": 40, "serving_size": "15g", "protein": "2g"}', 'Store in airtight container in cool dry place.', 4.20, 12, 400, 2500),
('Imli (Tamarind) Chutney (500ml)', 'imli-tamarind-chutney-500ml', 'Sweet and tangy tamarind chutney made from premium Konkan tamarind. Blended with jaggery and traditional spices. Perfect for chaats, samosas, and snacks.', 'Sweet tamarind chutney - 500ml, chaat essential', 149.00, 179.00, 350, 'PIC-IML-001', 6, 'Konkan Delight', 500, 'bottle', 0, 0, 0, 0, 'Goa', 365, 'Tamarind, Jaggery, Cumin, Ginger, Black Salt, Red Chili', '{"calories": 35, "serving_size": "30ml", "sugar": "8g"}', 'Refrigerate after opening.', 4.20, 15, 500, 3000),
('Green Chili Pickle - Konkan Style (300g)', 'green-chili-pickle-konkan-style-300g', 'Fiery green chili pickle made in traditional Konkan style. Fresh green chilies pickled with mustard oil and spices. For the brave spice lovers!', 'Spicy green chili pickle - 300g, Konkan style', 149.00, 189.00, 300, 'PIC-GRC-001', 6, 'Konkan Heritage', 300, 'jar', 0, 0, 0, 0, 'Ratnagiri', 540, 'Green Chili, Mustard Oil, Mustard Seeds, Turmeric, Salt, Vinegar', '{"calories": 15, "serving_size": "10g"}', 'Store in cool dry place.', 4.00, 10, 250, 2000),
('Kairi - Raw Mango Sliced Pickle (500g)', 'kairi-raw-mango-sliced-pickle-500g', 'Sliced raw mango pickle made in traditional Konkan style. Crisp mango slices marinated in aromatic spices and mustard oil. A seasonal favorite.', 'Sliced raw mango pickle - 500g, Konkan style', 179.00, 219.00, 400, 'PIC-KAI-001', 6, 'Konkan Heritage', 500, 'jar', 0, 0, 0, 0, 'Sindhudurg', 540, 'Raw Mango Slices, Mustard Oil, Red Chili, Turmeric, Fenugreek, Salt', '{"calories": 22, "serving_size": "15g"}', 'Store in cool dry place.', 4.30, 18, 450, 2800);
