('Organic Jaggery - Pure (1kg)', 'organic-jaggery-pure-1kg', 'Pure organic jaggery (Gud) made from sugarcane grown in the Konkan region. Golden brown, rich in iron and minerals. Traditionally processed without chemicals.', 'Pure organic jaggery - 1kg, iron-rich Konkan gud', 249.00, 299.00, 500, 'JAG-PUR-001', 9, 'Konkan Heritage', 1000, 'block', 1, 1, 0, 1, 'Ratnagiri', 540, 'Organic Sugarcane Jaggery', '{"calories": 40, "serving_size": "10g", "iron": "1.5mg", "calcium": "8mg", "magnesium": "5mg"}', 'Store in airtight container in cool dry place. May become soft in humid weather.', 4.50, 60, 2000, 14000),
('Palm Jaggery - Karupatti (1kg)', 'palm-jaggery-karupatti-1kg', 'Premium palm jaggery (Karupatti/Panai Vellam) from the Konkan region. Made from palm tree sap, rich in minerals with a distinct caramel-like flavor. Low glycemic index.', 'Palm jaggery - 1kg, low glycemic, mineral-rich', 399.00, 499.00, 250, 'JAG-PAL-001', 9, 'Konkan Heritage', 1000, 'block', 1, 0, 0, 1, 'Goa', 540, 'Pure Palm Jaggery', '{"calories": 35, "serving_size": "10g", "iron": "2mg", "calcium": "15mg", "glycemic_index": "Low"}', 'Store in airtight container in cool dry place.', 4.40, 25, 800, 6000),
('Coconut Jaggery - Organic (500g)', 'coconut-jaggery-organic-500g', 'Organic coconut jaggery made from the sap of coconut palm flowers. Rich, caramel-like sweetness with a low glycemic index. Mineral-rich and naturally processed.', 'Organic coconut jaggery - 500g, low glycemic', 299.00, 379.00, 300, 'JAG-COC-001', 9, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 1, 'Sindhudurg', 540, 'Organic Coconut Palm Jaggery', '{"calories": 38, "serving_size": "10g", "potassium": "130mg", "magnesium": "10mg"}', 'Store in airtight container in cool dry place.', 4.30, 15, 500, 3500),
('Jaggery Powder - Organic (500g)', 'jaggery-powder-organic-500g', 'Organic jaggery powder from Konkan sugarcane. Finely ground for easy use in cooking and baking. No additives or anti-caking agents.', 'Organic jaggery powder - 500g, fine ground', 179.00, 219.00, 400, 'JAG-PWD-001', 9, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 1, 'Ratnagiri', 540, 'Organic Jaggery Powder', '{"calories": 38, "serving_size": "10g", "iron": "1.2mg"}', 'Store in airtight container in cool dry place.', 4.10, 12, 400, 2500),
('Wild Honey - Raw (500ml)', 'wild-honey-raw-500ml', 'Pure raw wild honey from the forests of Konkan. Harvested from indigenous wild bee colonies in the Sahyadri forests. Rich, complex flavor with medicinal properties. Unfiltered and unpasteurized.', 'Raw wild honey - 500ml, Sahyadri forest honey', 899.00, 1099.00, 150, 'JAG-HON-001', 9, 'Konkan Heritage', 500, 'bottle', 1, 1, 0, 1, 'Sindhudurg', 1825, '100% Raw Wild Honey', '{"calories": 65, "serving_size": "20g", "sugar": "16g", "antioxidants": "High"}', 'Store in cool dry place away from direct sunlight. Natural crystallization may occur.', 4.70, 45, 1200, 10000),
('Multiflora Honey (500ml)', 'multiflora-honey-500ml', 'Pure multiflora honey from Konkan region apiaries. Bees collect nectar from diverse Konkan flora including mango blossoms, coconut flowers, and wildflowers. Smooth and sweet.', 'Multiflora honey - 500ml, Konkan blossoms', 499.00, 629.00, 300, 'JAG-HON-002', 9, 'Konkan Heritage', 500, 'bottle', 0, 0, 0, 1, 'Goa', 1825, '100% Pure Multiflora Honey', '{"calories": 65, "serving_size": "20g", "sugar": "16g"}', 'Store in cool dry place.', 4.30, 18, 600, 4500),
('Date Syrup (500ml)', 'date-syrup-500ml', 'Natural date syrup made from premium Medjool dates. No added sugar, no preservatives. A healthy, iron-rich natural sweetener. Perfect for drizzling over desserts, pancakes, or in smoothies.', 'Natural date syrup - 500ml, iron-rich sweetener', 349.00, 429.00, 200, 'JAG-DAT-001', 9, 'Konkan Bazaar Select', 500, 'bottle', 0, 0, 0, 1, 'Ratnagiri', 365, 'Date Extract', '{"calories": 60, "serving_size": "20g", "sugar": "14g", "iron": "1mg", "potassium": "120mg"}', 'Store in cool dry place. Refrigerate after opening.', 4.20, 10, 250, 2000);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Chakli - Konkan Style (500g)', 'chakli-konkan-style-500g', 'Crispy, spiral-shaped Konkan-style chakli (murukku) made from rice flour, gram flour, and traditional spices. Perfect tea-time snack, deep fried to golden perfection.', 'Crispy Konkan chakli - 500g, traditional spiral snack', 199.00, 249.00, 500, 'SNK-CHK-001', 10, 'Konkan Heritage', 500, 'pack', 1, 1, 0, 0, 'Ratnagiri', 60, 'Rice Flour, Gram Flour, Cumin Seeds, Sesame Seeds, Butter, Salt, Oil', '{"calories": 80, "serving_size": "20g", "fat": "4g", "fiber": "1g"}', 'Store in airtight container in cool dry place.', 4.40, 55, 2000, 12000),
('Kanda Poha - Instant Mix (500g)', 'kanda-poha-instant-mix-500g', 'Instant Kanda Poha mix from Konkan. Just add water and microwave for authentic Konkan breakfast. Made with thick Indrayani poha, roasted peanuts, and traditional spices.', 'Instant Kanda Poha mix - 500g, just add water', 149.00, 179.00, 400, 'SNK-POH-001', 10, 'Konkan Heritage', 500, 'pack', 0, 1, 0, 0, 'Sindhudurg', 180, 'Poha (Rice Flakes), Roasted Peanuts, Onion Flakes, Curry Leaves, Mustard Seeds, Turmeric, Salt, Sugar', '{"calories": 120, "serving_size": "50g prepared", "carbohydrates": "22g", "protein": "3g"}', 'Store in airtight container in cool dry place.', 4.30, 25, 1200, 5000),
('Bhakri - Jowar (10 pcs)', 'bhakri-jowar-10-pcs', 'Traditional Konkan-style Jowar (sorghum) bhakri. Hand-rolled and freshly prepared. A staple bread of Konkan region, perfect with brinjal bharta, curries, or chutney.', 'Traditional Jowar bhakri - 10 pieces, Konkan staple', 179.00, 219.00, 200, 'SNK-BHK-001', 10, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 0, 'Goa', 7, 'Jowar Flour, Water, Salt', '{"calories": 80, "serving_size": "1 bhakri", "fiber": "2g", "protein": "3g"}', 'Store in refrigerator. Reheat on tava before serving.', 4.20, 12, 350, 3000),
('Murukku - Spicy (500g)', 'murukku-spicy-500g', 'Spicy Konkan-style murukku made with rice flour, gram flour, and red chili. Extra crispy with a perfect crunch. An addictive tea-time snack.', 'Spicy murukku - 500g, Konkan style, extra crispy', 219.00, 269.00, 350, 'SNK-MUR-001', 10, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 0, 'Ratnagiri', 60, 'Rice Flour, Gram Flour, Red Chili Powder, Cumin Seeds, Butter, Salt, Oil', '{"calories": 85, "serving_size": "20g", "fat": "4.5g"}', 'Store in airtight container.', 4.30, 18, 600, 3500),
('Chivda - Pohe Mixture (500g)', 'chivda-pohe-mixture-500g', 'Konkan-style chivda made with thick poha (rice flakes), roasted peanuts, cashews, curry leaves, and spices. A traditional Konkan snack mix, perfect for travel and tea-time.', 'Konkan chivda - 500g, poha snack mix with nuts', 179.00, 219.00, 450, 'SNK-CHV-001', 10, 'Konkan Heritage', 500, 'pack', 0, 1, 0, 0, 'Sindhudurg', 90, 'Poha, Peanuts, Cashews, Curry Leaves, Mustard Seeds, Turmeric, Chili, Salt, Oil, Sugar', '{"calories": 90, "serving_size": "20g", "fat": "4g", "protein": "2g"}', 'Store in airtight container in cool dry place.', 4.30, 22, 900, 4500),
('Sabudana Khichdi Mix (500g)', 'sabudana-khichdi-mix-500g', 'Instant Sabudana khichdi mix from Konkan. Premium sabudana (tapioca pearls) pre-mixed with roasted peanuts and spices. Just soak and cook for a delicious fasting dish.', 'Instant Sabudana khichdi mix - 500g, fasting special', 199.00, 249.00, 300, 'SNK-SAB-001', 10, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 0, 'Goa', 180, 'Sabudana (Tapioca Pearls), Roasted Peanuts, Cumin, Green Chili, Salt, Sugar, Ghee', '{"calories": 150, "serving_size": "50g prepared", "carbohydrates": "32g", "protein": "2g"}', 'Store in airtight container in cool dry place.', 4.10, 10, 300, 2500),
('Roasted Bengal Gram - Daliya (500g)', 'roasted-bengal-gram-daliya-500g', 'Roasted Bengal gram (Daliya/Chana Dal) from Konkan. Lightly roasted for a nutty, crunchy snack. High in protein and fiber. A healthy traditional Konkan snack.', 'Roasted Bengal gram - 500g, protein-rich snack', 129.00, 159.00, 500, 'SNK-DAL-001', 10, 'Konkan Heritage', 500, 'pack', 0, 0, 0, 0, 'Ratnagiri', 365, 'Roasted Bengal Gram, Salt', '{"calories": 60, "serving_size": "20g", "protein": "4g", "fiber": "2.5g"}', 'Store in airtight container in cool dry place.', 4.00, 8, 350, 2000),
('Peanut Chikki (250g)', 'peanut-chikki-250g', 'Traditional Konkan-style peanut chikki (gachak). Crunchy peanuts bound in pure jaggery syrup. A classic Konkan winter snack that is both delicious and nutritious.', 'Traditional peanut chikki - 250g, jaggery based', 149.00, 189.00, 350, 'SNK-CHI-001', 10, 'Konkan Heritage', 250, 'pack', 0, 1, 0, 0, 'Sindhudurg', 90, 'Peanuts, Jaggery, Ghee', '{"calories": 110, "serving_size": "25g", "protein": "4g", "sugar": "12g"}', 'Store in airtight container in cool dry place.', 4.40, 20, 800, 4000),
('Til Laddoo - Sesame (250g)', 'til-laddoo-sesame-250g', 'Traditional Konkan-style til (sesame) laddoos made with black sesame seeds and jaggery. A winter special sweet that is rich in calcium and iron. Made during Makar Sankranti.', 'Sesame laddoos - 250g, calcium-rich winter sweet', 179.00, 219.00, 250, 'SNK-TIL-001', 10, 'Konkan Heritage', 250, 'pack', 0, 0, 0, 0, 'Goa', 60, 'Black Sesame Seeds, Jaggery, Peanuts, Cardamom', '{"calories": 130, "serving_size": "25g", "calcium": "100mg", "iron": "2mg"}', 'Store in airtight container in cool dry place.', 4.30, 12, 350, 2800),
('Puran Poli - Ready to Eat (4 pcs)', 'puran-poli-ready-to-eat-4-pcs', 'Traditional Konkan-style Puran Poli. Soft wheat rotis stuffed with sweet chana dal filling (puran). Heat and serve. A festive Maharashtrian delicacy.', 'Ready-to-eat Puran Poli - 4 pieces, festive sweet', 249.00, 299.00, 150, 'SNK-PUR-001', 10, 'Konkan Heritage', 400, 'pack', 0, 0, 0, 0, 'Ratnagiri', 15, 'Wheat Flour, Chana Dal, Jaggery, Cardamom, Nutmeg, Ghee', '{"calories": 200, "serving_size": "1 piece", "sugar": "15g", "protein": "5g"}', 'Store in refrigerator. Reheat on tava before serving.', 4.40, 15, 250, 3500);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Handwoven Bamboo Basket - Medium', 'handwoven-bamboo-basket-medium', 'Handcrafted bamboo basket woven by skilled Konkan artisans. Made from sustainably harvested bamboo. Perfect for storage, shopping, or home decor. Each piece is unique.', 'Handwoven Konkan bamboo basket - Medium, artisan made', 599.00, 749.00, 50, 'CRF-BAM-001', 11, 'Konkan Heritage', 500, 'piece', 0, 0, 0, 0, 'Sindhudurg', 9999, 'Natural Bamboo', '{"craft": "Handwoven Bamboo", "material": "Natural Bamboo"}', 'Keep in dry place. Wipe with dry cloth. Avoid moisture.', 4.50, 15, 150, 2500),
('Konkan Clay Diya Set (6 pcs)', 'konkan-clay-diya-set-6-pcs', 'Handcrafted clay diyas (lamps) from Konkan potters. Each diya is shaped, sun-dried, and naturally finished. Perfect for Diwali and festive decorations.', 'Handcrafted clay diyas - 6 pieces, Konkan pottery', 249.00, 299.00, 100, 'CRF-DIY-001', 11, 'Konkan Heritage', 600, 'set', 0, 0, 0, 0, 'Ratnagiri', 9999, 'Natural Clay', '{"craft": "Clay Pottery", "material": "Natural Clay"}', 'Handle with care. Store in dry place.', 4.30, 8, 200, 1800),
('Souvenir - Konkan Coconut Shell Carving', 'souvenir-konkan-coconut-shell-carving', 'Intricately carved coconut shell souvenir from Konkan. Each piece hand-carved by local artisans depicting traditional Konkan scenes. Unique gift item.', 'Hand-carved coconut shell - Konkan souvenir, artisan craft', 399.00, 499.00, 75, 'CRF-COC-001', 11, 'Konkan Heritage', 200, 'piece', 0, 0, 0, 0, 'Goa', 9999, 'Dried Coconut Shell', '{"craft": "Coconut Shell Carving", "material": "Coconut Shell"}', 'Handle with care. Keep in dry place.', 4.40, 10, 100, 1500),
('Konkan Handloom Cotton Towel (2 pcs)', 'konkan-handloom-cotton-towel-2-pcs', 'Handwoven cotton towels from Konkan handloom weavers. Soft, absorbent, and lightweight. Traditional Konkan checkered pattern. Eco-friendly and sustainable.', 'Handloom cotton towels - 2 pieces, Konkan weave', 449.00, 549.00, 80, 'CRF-TOW-001', 11, 'Konkan Heritage', 400, 'set', 0, 0, 0, 1, 'Sindhudurg', 9999, '100% Handloom Cotton', '{"craft": "Handloom Weaving", "material": "Cotton"}', 'Machine washable. Wash before first use.', 4.30, 8, 120, 1200),
('Konkan Spice Box - Wooden (7 Spice)', 'konkan-spice-box-wooden-7-spice', 'Traditional Konkan wooden spice box (Masala Dabba) with 7 stainless steel cups. Handcrafted from locally sourced mango wood. Perfect kitchen companion for Konkan cooking.', 'Handcrafted wooden spice box - 7 spice, mango wood', 799.00, 999.00, 60, 'CRF-SPX-001', 11, 'Konkan Heritage', 800, 'piece', 0, 0, 0, 0, 'Ratnagiri', 9999, 'Mango Wood, Stainless Steel, Natural Lacquer', '{"craft": "Wood Carving", "material": "Mango Wood"}', 'Wipe with dry cloth. Keep away from water. Apply coconut oil occasionally.', 4.60, 20, 250, 3000);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Monsoon Bhajji Mix - Special (500g)', 'monsoon-bhajji-mix-special-500g', 'Special Konkan monsoon bhajji (pakora) mix. A blend of gram flour, rice flour, and traditional spices. Just add sliced onions, chilies, or vegetables and fry for crispy monsoon bhajjis.', 'Monsoon bhajji mix - 500g, crispy pakora mix', 149.00, 179.00, 500, 'MON-BHA-001', 12, 'Konkan Heritage', 500, 'pack', 1, 1, 1, 0, 'Ratnagiri', 180, 'Gram Flour, Rice Flour, Red Chili, Cumin, Ajwain, Salt, Baking Soda', '{"calories": 60, "serving_size": "20g prepared", "fat": "3g"}', 'Store in airtight container in cool dry place.', 4.30, 30, 1200, 6000),
('Monsoon Special - Dried Shrimp Bhaji Mix (300g)', 'monsoon-special-dried-shrimp-bhaji-mix-300g', 'Special Konkan monsoon mix with dried shrimp and spices. Just add water and fry for an authentic coastal fritter that pairs perfectly with hot chai on rainy days.', 'Dried shrimp bhaji mix - 300g, coastal monsoon snack', 199.00, 249.00, 300, 'MON-SHR-001', 12, 'Konkan Heritage', 300, 'pack', 0, 0, 1, 0, 'Sindhudurg', 180, 'Dried Shrimp, Gram Flour, Rice Flour, Red Chili, Spices, Salt', '{"calories": 70, "serving_size": "20g"}', 'Store in airtight container in cool dry place.', 4.20, 12, 350, 2800),
('Hot Masala Tea - Konkan Chai Mix (500g)', 'hot-masala-tea-konkan-chai-mix-500g', 'Special Konkan masala chai mix with cardamom, ginger, cinnamon, and black pepper. Just add to milk and tea leaves for authentic Konkan-style cutting chai. Perfect for monsoon evenings.', 'Konkan masala chai mix - 500g, monsoon companion', 249.00, 299.00, 400, 'MON-TEA-001', 12, 'Konkan Heritage', 500, 'pack', 0, 1, 1, 0, 'Goa', 365, 'Tea Powder, Cardamom, Ginger, Cinnamon, Black Pepper, Cloves, Mace', '{"calories": 5, "serving_size": "5g"}', 'Store in airtight container in cool dry place.', 4.50, 35, 1500, 6500),
('Corn Roasted - Bhutta Masala (200g)', 'corn-roasted-bhutta-masala-200g', 'Special Konkan-style roasted corn (bhutta) seasoning mix. A tangy, spicy blend with lemon, chili, and special Konkan spices. Sprinkle on roasted corn for the perfect monsoon street food experience.', 'Bhutta masala seasoning - 200g, monsoon street food', 89.00, 109.00, 500, 'MON-BHU-001', 12, 'Konkan Heritage', 200, 'pack', 0, 0, 1, 0, 'Ratnagiri', 540, 'Red Chili, Lemon Powder, Cumin, Black Salt, Coriander, Mango Powder', '{"calories": 5, "serving_size": "5g"}', 'Store in airtight container.', 4.10, 10, 400, 2000),
('Soup Mix - Konkan Tomato Rasam (200g)', 'soup-mix-konkan-tomato-rasam-200g', 'Instant Konkan-style tomato rasam mix. A warm, spicy-sour soup that is a monsoon favorite. Made with authentic Konkan spices. Just add water, tomatoes, and simmer.', 'Instant tomato rasam mix - 200g, warm monsoon soup', 99.00, 129.00, 400, 'MON-RAS-001', 12, 'Konkan Heritage', 200, 'pack', 0, 0, 1, 0, 'Sindhudurg', 365, 'Coriander, Cumin, Pepper, Red Chili, Turmeric, Asafoetida, Garlic, Tamarind, Salt', '{"calories": 10, "serving_size": "10g"}', 'Store in airtight container in cool dry place.', 4.20, 12, 500, 3000),
('Bhel Puri Mix (500g)', 'bhel-puri-mix-500g', 'Ready-to-eat bhel puri mix from Konkan. Crispy puffed rice, sev, peanuts, and spices in perfect proportion. Just add chutneys and chopped onions for instant bhel puri - the perfect monsoon snack.', 'Ready bhel puri mix - 500g, instant monsoon snack', 149.00, 179.00, 400, 'MON-BHE-001', 12, 'Konkan Heritage', 500, 'pack', 0, 0, 1, 0, 'Goa', 60, 'Puffed Rice, Sev, Peanuts, Roasted Gram, Onion, Tomato Powder, Spices, Salt', '{"calories": 80, "serving_size": "20g", "fat": "3g"}', 'Store in airtight container in cool dry place.', 4.20, 15, 600, 3500);
INSERT INTO products (name, slug, description, short_description, price, mrp, stock_quantity, sku, category_id, brand, weight_grams, unit, is_featured, is_bestseller, is_seasonal, is_organic, region_origin, shelf_life_days, ingredients, nutritional_info, storage_instructions, average_rating, review_count, total_sold, views_count) VALUES
('Kokum Sharbat - Concentrate (1L)', 'kokum-sharbat-concentrate-1l', 'Traditional Konkan Kokum Sharbat concentrate. Made from real kokum extract with a hint of cumin and black salt. A digestive and cooling drink perfect for summer and monsoon.', 'Kokum Sharbat concentrate - 1L, digestive drink', 249.00, 299.00, 300, 'BEV-KOK-001', 5, 'Konkan Delight', 1000, 'bottle', 0, 0, 0, 0, 'Ratnagiri', 365, 'Kokum Extract, Sugar, Cumin, Black Salt, Water', '{"calories": 45, "serving_size": "30ml", "sugar": "10g"}', 'Store in cool dry place. Refrigerate after opening.', 4.30, 20, 500, 3500),
('Salted Cashew - Premium (1kg)', 'salted-cashew-premium-1kg', 'Premium salted cashew nuts in bulk pack. W180 grade cashews from Goa, roasted and lightly salted. Perfect for parties, gifting, and everyday snacking.', 'Premium salted cashews - 1kg, party pack', 999.00, 1249.00, 200, 'CAS-SAL-BULK-001', 7, 'Konkan Bazaar Select', 1000, 'pack', 0, 0, 0, 0, 'Goa', 180, 'Cashew Nuts, Salt, Vegetable Oil', '{"calories": 160, "serving_size": "30g", "protein": "5g", "fat": "13g"}', 'Store in airtight container in cool dry place.', 4.50, 25, 800, 5000),
('Spicy Cashew - Extra Hot (500g)', 'spicy-cashew-extra-hot-500g', 'Extra hot spicy cashew nuts for daring snack lovers. Konkan cashews coated with fiery red chili and special spice blend. Not for the faint-hearted!', 'Extra hot spicy cashews - 500g, fiery snack', 579.00, 729.00, 200, 'CAS-SPX-001', 7, 'Konkan Bazaar Select', 500, 'pack', 0, 0, 0, 0, 'Goa', 180, 'Cashew Nuts, Red Chili, Chaat Masala, Black Pepper, Salt, Oil', '{"calories": 165, "serving_size": "30g", "protein": "5g", "fat": "13g"}', 'Store in airtight container.', 4.20, 15, 500, 3500);
