INSERT INTO reviews (product_id, user_id, rating, title, body, is_verified_purchase, is_approved) VALUES
(1, 2, 5, 'Best Alphonso Mangoes Ever!', 'These Devgad Alphonso mangoes are incredible. So sweet and flavorful. The packaging was perfect and they arrived in great condition. Will definitely order again!', 1, 1),
(1, 3, 4, 'Very Good Quality', 'The mangoes were very fresh and sweet. A bit pricey but worth it for the quality. Gift packaging was beautiful.', 1, 1),
(2, 5, 5, 'Taste of Konkan', 'Brought back memories of my childhood in Ratnagiri. These mangoes are the real deal. Highly recommended!', 1, 1),
(26, 2, 5, 'Authentic Bombil', 'The dried bombil is excellent quality. Made traditional Konkan bombil fry and it tasted just like back home.', 1, 1),
(51, 3, 5, 'Pure Coconut Oil', 'This is the real deal - pure cold-pressed coconut oil with amazing aroma. Great for cooking and hair care.', 1, 1),
(66, 2, 5, 'Best Indrayani Rice', 'The aroma of this rice while cooking is incredible. Perfect for daily use and special occasions.', 1, 1),
(86, 4, 5, 'Refreshing Sol Kadhi', 'Perfect sol kadhi concentrate. Tastes just like homemade. Great for digestion after meals.', 1, 1),
(116, 5, 4, 'Crunchy and Fresh', 'The roasted cashews are very fresh and crunchy. Good value for the price.', 1, 1);
INSERT INTO site_settings (setting_key, value) VALUES
('homepage_meta_title', 'Konkan Bazaar - Authentic Konkan Products Online'),
('homepage_meta_description', 'Shop authentic Konkan region products including Alphonso mangoes, cashews, spices, seafood, and traditional delicacies. Direct from farmers and artisans of Konkan.'),
('about_us', 'Konkan Bazaar is your trusted online marketplace for authentic products from the Konkan region - the beautiful coastal belt of Maharashtra, Goa, and Karnataka. We connect you directly with local farmers, fishermen, and artisans who have been crafting these products for generations.'),
('returns_policy', 'We accept returns within 7 days of delivery for damaged or defective items. Perishable food items cannot be returned once opened.'),
('shipping_policy', 'Free shipping on orders above ₹499. Standard delivery within 3-5 business days. Express delivery available at extra charge.'),
('privacy_policy', 'We take your privacy seriously. Your personal information is encrypted and never shared with third parties without your consent.'),
('terms_of_service', 'By using Konkan Bazaar, you agree to our terms and conditions. All prices are in INR and inclusive of applicable taxes.');
